-- Rifts World Book 21: Splynn Dimensional Market - its bestiary and its notable NPCs.
-- 0 creatures (migration 074) and 4 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~375-splynn-npcs-b.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('krynn-katar', 'K''Rynn Katar', NULL, 'The Bone Merchant; proprietor of the Bone Merchant shop, Splynn', 'rifts', 'Greater Demon; appears to be a typical C''ro Demon Mage (as printed)', '8th level Necromancer (as printed)', 8, 'Diabolic', NULL, NULL, NULL, '{"IQ":16,"ME":22,"MA":20,"PS":18,"PP":14,"PE":14,"PB":4,"Spd":10}', NULL, NULL, 550, 350, NULL, NULL, 15, NULL, 'The block prints no attacks per melee and no combat bonuses; none is stored or derived. M.D.C. 550 is printed as plus any gained from Necromantic augmentation.', NULL, 'No skill list is printed.', 'Has the abilities of his kind: nightvision, sees the invisible, Dimensional Teleport 75%, Bio-Regenerates 4D6 M.D. each melee round, cannot be harmed by disease, possession, symbiotic union, vampire mind control or ordinary fire and cold, takes half damage from M.D. fire and cold, and knows all languages by magic.', 'All common spells of levels 1-5, a handful of spells of levels 6-12, and all Necro-Magic and Necromancer abilities at 8th level. P.P.E. 350.', 'None.', NULL, NULL, 'Always carries bones from several creatures, and a ceremonial silver-plated dagger set with gems worth one million credits (no damage printed).', NULL, 'Diabolic, yet straight dealing in most of his trade. Wary and discreet: he sells forbidden dragon remains only to buyers who pay up front and pass a magical inspection, and helps Splynn''s authorities sting rival dragon-bone traders to cut competition and keep suspicion off himself.', NULL, NULL, 'A red-skinned, yellow-eyed C''ro Demon Mage with six jointed stingers on his back and an air of death about him. His shop is lined with skulls, bones and skeletons of rare and powerful beings from across the Megaverse; he opened it mainly to feed his own Necromancy and sells the surplus. Dragon bones, revered and banned in Atlantis, are his secret and most lucrative trade, priced at five to ten times the usual rate. He would pay a fortune for the Skull of Osiris, said to be bonded to a mad Necromancer roaming Africa, and a reward for word of where that Necromancer can be found.', 'Rifts World Book 21: Splynn Dimensional Market p.25-27'),
('dionna', 'Dionna', NULL, 'Owner of Chaotic Spirits, Splynn; alleged daughter of Dionysus', 'rifts', 'Demi-God (as printed); a godling/demoness', '10th level godling/demon hybrid (as printed)', 10, 'Miscreant', NULL, NULL, NULL, '{"IQ":22,"ME":25,"MA":22,"PS":23,"PP":17,"PE":26,"PB":24,"Spd":18}', NULL, NULL, 852, 323, 73, NULL, 13, NULL, 'The block prints no attacks per melee and no combat bonuses; none is stored or derived. Her H.F. of 13 comes from an aura of evil.', NULL, 'No skill list is printed. She has full knowledge of mystic herbology and of all magic and demon lore skills.', 'Identifies any poison, toxin or magic potion by taste, knowing its effects, duration and antidote but not its maker, and can cancel any of them with a touch, even one she has already swallowed. Shoots magic flames from her eyes (500 feet/152.4 m, 4D6 M.D., see attacks), sees the invisible, nightvision to 600 feet (183 m), Bio-Regenerates 4D6 M.D.C. each minute, has Dimensional Teleport at 45%, and takes half damage from heat and fire. Vulnerabilities: holy water burns her like acid for 3D6 M.D. per vial, and natural or magical lightning does her double damage (artificial electricity and ion weapons do normal damage), possibly a curse laid by Zeus.', 'No spell list is printed: full knowledge of mystic herbology and all magic and demon lore skills. P.P.E. 323.', 'All Healing and Sensitive powers; I.S.P. 73. Counted as a Major Psionic.', NULL, NULL, 'A magic chalice that doubles the potency of any potion poured from it, and a lesser Rune dagger (6D6 M.D., see attacks).', NULL, 'Decadent, cruel and proud. She personally vouches for the potions she sells, and turns rumours that she stole her recipes from Dionysus into proof of her divine birth.', NULL, NULL, 'A strikingly beautiful demigoddess with chalk-white skin, nearly black red hair, red eyes and fangs, said to be the child of Dionysus and a demoness. Among the first to settle permanently in the Market, she owns Chaotic Spirits, the grandest tavern in Atlantis, where rich supernatural patrons are served enchanted liquors, magic potions and drinks that often kill humans. Twenty Druids and Herbalists and forty chained Faerie Folk keep it stocked, and its house wine, The Nectar, can get even demons and gods drunk.', 'Rifts World Book 21: Splynn Dimensional Market p.27-28'),
('re-animator', 'The Re-Animator', 'Unknown; true name and identity unknown (as printed)', 'Owner and operator of the Re-Animator, Splynn', 'rifts', 'Unknown; appears to be human or human-like (as printed)', '14th level Necromancer (as printed)', 14, 'Aberrant', NULL, NULL, NULL, '{"IQ":20,"ME":22,"MA":16,"PS":20,"PP":20,"PE":16,"PB":17,"Spd":14}', NULL, NULL, 180, 200, NULL, NULL, 14, NULL, 'The block prints no attacks per melee and no combat bonuses; none is stored or derived. M.D.C. 180 does not count armor or magical defenses.', NULL, 'No skill list is printed.', 'Every Necromancer O.C.C. power, plus nightvision to 100 feet (30.5 m), sees the invisible, and knows all languages by magic. She may hold more demonic or godly powers that nobody has confirmed; she is thought to be far more than human.', 'All Bone Magic and Necro-Magic and the related Wizard spells. P.P.E. 200.', 'Unknown; suspected to be at least a minor psychic (needs 12 or higher to save).', NULL, NULL, 'A large collection of bones, and weapons and gear for fighting the undead, spirits and demons.', NULL, 'Aberrant, and her word is her bond. Secretive: she works on the dead alone and throws out anyone who tries to watch, and she uses up her slaves without a qualm.', NULL, NULL, 'A young, attractive woman who never seems to age, wrapped in shadow and smoke, with tattoos that include T-Man images though she is no True Atlantean and draws no power from Tattoo Magic. Her shop raises the dead for a steep fee in credits or service, and sells other necromantic services, charms against the undead, books and anti-undead weapons. Two dozen chained Tattooed Men bearing the Phoenix tattoo, plus some greater demons and healers, do much of the resurrecting; burnt-out T-Men become living batteries for her secret projects. Rumour says she once advised the Pharaoh Rama-Set.', 'Rifts World Book 21: Splynn Dimensional Market p.31-33'),
('crazy-al', 'Crazy Al', NULL, 'Owner of Crazy Al''s House of Crazies, Splynn', 'rifts', NULL, '12th level Master Psychic (as printed); rumoured once to have been a Mind Mage or a Psi-Tech', 12, 'Miscreant', NULL, NULL, NULL, NULL, NULL, NULL, 236, NULL, 210, NULL, NULL, NULL, 'A sketch, not a stat block: the book prints alignment, level, M.D.C., I.S.P. and a psi-power list only. No race, attributes, attacks or bonuses are printed; none is stored or derived.', NULL, NULL, NULL, NULL, 'Mind Block, Meditation, Psychic Surgery, Psychic Diagnosis, Detect Psionics, Sense Magic, See The Invisible, Telekinesis (printed as Telekinesis (basic)), Machine Ghost, Bio-Manipulation (the evil eye), Electrokinesis and all Telemechanic abilities; I.S.P. 210. Bio-Manipulation is printed without its catalog suffix. His powers are limited, perhaps by trauma and insanity.', NULL, NULL, NULL, NULL, 'Jittery, excitable and psychotic, obsessed with Crazies and M.O.M. technology, and convinced that an implant taken out of a living subject is ruined.', NULL, NULL, 'A slaver and amateur scientist who trades only in M.O.M.-augmented Crazies and their variants, the Kill Crazy among them, which few non-Splugorth merchants handle. He leaves the Market for months at a time and comes back with a truckload of stock. He also sells M.O.M. conversions, safe ones at the usual price and experimental ones cheaply to see whether they work, and tries to copy implants with his Telemechanic powers while they are still inside living subjects.', 'Rifts World Book 21: Splynn Dimensional Market p.38-39');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('notable_npc', 'dionna', 'Eye flames', '4D6 M.D.', 1, '500 feet (152.4 m)', 'Magic flames projected from her eyes.', 0),
('notable_npc', 'dionna', 'Lesser rune dagger', '6D6 M.D.', 1, NULL, 'A lesser Rune Weapon.', 1);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 notable NPCs are in' AS assertion, count(*) AS got, 4 AS want
  FROM notable_npcs WHERE slug IN ('krynn-katar', 'dionna', 're-animator', 'crazy-al');
SELECT 'and the notables 2' AS assertion, count(*) AS got, 2 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('krynn-katar', 'dionna', 're-animator', 'crazy-al');

